css:
.rabc-wrapper {
	font-family: Helvetica, Arial, sans-serif;
	color: #2b2b2b;
	font-size: 10px;
}

.rabc-header-table {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 10px;
}

.rabc-header-table td {
	vertical-align: top;
	padding: 0;
}

.rabc-company-name {
	font-size: 18px;
	font-weight: bold;
	color: #0f1e38;
	margin: 0 0 2px 0;
}

.rabc-company-meta {
	font-size: 9px;
	color: #6b7a99;
	line-height: 1.5;
}

.rabc-title-box {
	background-color: #0f1e38;
	color: #ffffff;
	text-align: center;
	padding: 8px 10px;
}

.rabc-title-box .rabc-title {
	font-size: 14px;
	font-weight: bold;
	letter-spacing: 1px;
	text-transform: uppercase;
	color: #f0ca4a;
}

.rabc-title-box .rabc-subtitle {
	font-size: 9px;
	color: #d8dce6;
	margin-top: 2px;
}

.rabc-gold-rule {
	height: 3px;
	background-color: #c9a520;
	margin-bottom: 10px;
	font-size: 1px;
	line-height: 1px;
}

.rabc-meta-table {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 10px;
}

.rabc-meta-table td {
	vertical-align: top;
	padding: 6px 8px;
	background-color: #f7f8fa;
	border: 1px solid #e8eaf0;
	font-size: 9px;
}

.rabc-meta-label {
	color: #6b7a99;
	text-transform: uppercase;
	font-size: 7.5px;
	letter-spacing: 0.5px;
}

.rabc-meta-value {
	color: #0f1e38;
	font-weight: bold;
	font-size: 10px;
}

.rabc-section-heading {
	background-color: #0f1e38;
	color: #ffffff;
	font-size: 9px;
	font-weight: bold;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	padding: 5px 8px;
	margin-top: 10px;
	margin-bottom: 0;
}

.rabc-items-table {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 10px;
}

.rabc-items-table th {
	background-color: #eef0f4;
	color: #0f1e38;
	font-size: 8.5px;
	text-transform: uppercase;
	letter-spacing: 0.3px;
	padding: 5px 6px;
	border: 1px solid #d8dce6;
	text-align: left;
}

.rabc-items-table td {
	padding: 5px 6px;
	border: 1px solid #d8dce6;
	font-size: 9px;
	vertical-align: top;
}

.rabc-items-table .rabc-num {
	text-align: right;
	white-space: nowrap;
}

.rabc-waterfall-table {
	width: 60%;
	border-collapse: collapse;
	margin-left: 40%;
	margin-top: 8px;
}

.rabc-waterfall-table td {
	padding: 5px 8px;
	font-size: 9.5px;
	border-bottom: 1px solid #e8eaf0;
}

.rabc-waterfall-table .rabc-wf-label {
	color: #3a4a6b;
}

.rabc-waterfall-table .rabc-wf-amount {
	text-align: right;
	white-space: nowrap;
	color: #0f1e38;
}

.rabc-waterfall-table .rabc-wf-deduction .rabc-wf-amount {
	color: #c0392b;
}

.rabc-waterfall-table .rabc-wf-subtotal td {
	background-color: #fdf6e0;
	font-weight: bold;
	color: #0f1e38;
	border-top: 2px solid #c9a520;
	border-bottom: 2px solid #c9a520;
}

.rabc-waterfall-table .rabc-wf-vat .rabc-wf-amount {
	color: #1a7f4b;
}

.rabc-waterfall-table .rabc-wf-final td {
	background-color: #0f1e38;
	color: #ffffff;
	font-weight: bold;
	font-size: 11px;
	border-bottom: none;
}

.rabc-waterfall-table .rabc-wf-final .rabc-wf-amount {
	color: #f0ca4a;
}

.rabc-footer-table {
	width: 100%;
	border-collapse: collapse;
	margin-top: 24px;
}

.rabc-footer-table td {
	vertical-align: top;
	padding: 0 8px;
	font-size: 8.5px;
	color: #6b7a99;
}

.rabc-sign-line {
	border-top: 1px solid #3a4a6b;
	margin-top: 30px;
	padding-top: 4px;
	color: #0f1e38;
	font-weight: bold;
	font-size: 9px;
}

.rabc-terms {
	margin-top: 10px;
	font-size: 8.5px;
	color: #6b7a99;
	line-height: 1.5;
}
